parameters.jsCode:
// Merge LLM classification with original email fields for downstream nodes
const raw = $json.raw || '';
const cleaned = raw.replace(/```json\n?|```/g, '').trim();
let classification;
try {
  classification = JSON.parse(cleaned);
} catch (e) {
  // Fail safe: treat unparseable output as needs human review
  classification = { category: 'other', priority: 'normal', needs_reply: true, skip_reason: '', summary: 'Classification failed - please review manually.', follow_ups: [] };
}
const email = $('Gmail Trigger').first().json;
return [{
  json: {
    ...classification,
    messageId: email.id,
    threadId: email.threadId,
    from: email.From?.value || email.headers?.from || '',
    subject: email.Subject || email.subject || '',
    body: email.text || email.snippet || ''
  }
}];

